fn combiner_skip_inductive(pre: Self, post: Self) {
    assert(pre.clients_complete());
    assert(pre.slots_complete());
    assert(pre.clients_size());
    assert(pre.not_waiting_inv());
    assert(pre.waiting_inv());
    assert(pre.request_stored_inv());
    assert(pre.response_stored_inv());
    assert(pre.combiner_has_inv());

    assert(post.clients_complete());
    assert(post.slots_complete());
    assert(post.not_waiting_inv());
    assert(post.request_stored_inv());
    assert(post.response_stored_inv());

    assert(post.combiner.is_Collecting());
    let old_elems = pre.combiner.get_Collecting_elems();
    let j = old_elems.len();
    let new_elems = post.combiner.get_Collecting_elems();
    assert(new_elems == old_elems.push(Option::None));
    assert(new_elems.len() == old_elems.len() + 1);
    assert(new_elems.len() <= post.num_clients);

    assert forall |i: nat| post.combiner_has(i) implies pre.combiner_has(i) by {
        if post.combiner_has(i) {
            assert(i < new_elems.len());
            assert(new_elems.index(i as int).is_Some());
            assert(i != j);
            assert(i < old_elems.len());
            assert(old_elems.index(i as int) == new_elems.index(i as int));
            assert(pre.combiner_has(i));
        }
    }

    assert(post.clients_size());
    assert(post.waiting_inv());
    assert(post.combiner_has_inv());
}

